    enonce: "<span class=\"q\">1) </span>أجب بصواب أو خطأ مع التعليل: مهما يكن العدد الصحيح n فإنّ <span dir=\"ltr\" class=\"expr\">36n + 12</span> يقبل القسمة على 6<br><span class=\"q\">2) </span>أجب بصواب أو خطأ مع التعليل: باقي القسمة الإقليدية لـ 1314 على 9 هو 0<br><span class=\"q\">3) </span>أجب بصواب أو خطأ مع التعليل: مهما يكن الرقم a فإنّ العدد 882a0 يقبل القسمة على 10<br><span class=\"q\">4) </span>أجب بصواب أو خطأ مع التعليل: عدد صحيح زوجي و عدد صحيح فردي يكونان دائما أوليين فيما بينهما",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نقسم المعامل الأوّل","math":"<span dir=\"ltr\" class=\"expr\">36 = 6 × 6</span>"},{"quoi":"نقسم الحدّ الثابت","math":"<span dir=\"ltr\" class=\"expr\">12 = 6 × 2</span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">36n + 12 = 6(6n + 2)</span>"},{"quoi":"نستنتج","math":"العبارة مكتوبة <span dir=\"ltr\" class=\"expr\">6 ×</span> عدد صحيح، مهما يكن n"},{"quoi":"الجواب","math":"صواب"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نبحث عن الخارج","math":"أكبر مضاعف لـ 9 لا يفوق 1314 هو <span dir=\"ltr\" class=\"expr\">9 × 146</span>"},{"quoi":"نحسب هذا المضاعف","math":"<span dir=\"ltr\" class=\"expr\">9 × 146 = 1314</span>"},{"quoi":"نحسب الباقي","math":"<span dir=\"ltr\" class=\"expr\">1314 - 1314 = 0</span>"},{"quoi":"نتحقّق من الشرط","math":"<span dir=\"ltr\" class=\"expr\">0 &lt; 9</span>"},{"quoi":"نكتب القسمة الإقليدية","math":"<span dir=\"ltr\" class=\"expr\">1314 = 9 × 146 + 0</span>"},{"quoi":"الجواب","math":"صواب"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"شرط القسمة على 10","math":"العدد يقبل القسمة على 10 إذا كان رقم آحاده 0"},{"quoi":"رقم الآحاد معلوم","math":"رقم آحاد العدد 882a0 هو 0"},{"quoi":"الشرط لا يتعلّق بـ a","math":"الشرط يتعلّق برقم الآحاد وحده، و هو 0 مهما يكن a"},{"quoi":"نستنتج","math":"العدد يقبل القسمة على 10 مهما يكن a"},{"quoi":"الجواب","math":"صواب"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"ما تقوله العبارة","math":"العبارة تدّعي أنّ الزوجية و الفردية تكفيان للأوّلية فيما بينهما"},{"quoi":"نبحث عن مثال مضادّ","math":"نأخذ 6 و هو زوجي، و 15 و هو فردي"},{"quoi":"نفكّك العددين","math":"<span dir=\"ltr\" class=\"expr\">6 = 3 × 2</span> و <span dir=\"ltr\" class=\"expr\">15 = 3 × 5</span>"},{"quoi":"نحسب القاسم المشترك","math":"العدد 3 يقسم 6 و يقسم 15"},{"quoi":"نستنتج","math":"ق.م.أ لهما يقبل القسمة على 3 فهو ليس 1"},{"quoi":"الجواب","math":"خطأ"}],
