    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نفكّك العبارة الأولى","math":"<span dir=\"ltr\" class=\"expr\">28n + 14 = 7(4n + 2)</span>"},{"quoi":"نفكّك العبارة الثانية","math":"<span dir=\"ltr\" class=\"expr\">14n + 14 = 7(2n + 2)</span>"},{"quoi":"نستنتج قاسما مشتركا","math":"العدد 7 يقسم العبارتين مهما يكن n"},{"quoi":"نقارن بالتعريف","math":"عددان أوليان فيما بينهما ق.م.أ لهما يساوي 1، و هنا ق.م.أ يقبل القسمة على 7"},{"quoi":"الجواب","math":"خطأ"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نسمّي رقم المئات","math":"نسمّي n رقم المئات، فتكون الأرقام n و <span dir=\"ltr\" class=\"expr\">n + 1</span> و <span dir=\"ltr\" class=\"expr\">n + 2</span>"},{"quoi":"شرط القسمة على 9","math":"العدد يقبل القسمة على 9 إذا كان مجموع أرقامه يقبل القسمة على 9"},{"quoi":"نحسب مجموع الأرقام","math":"<span dir=\"ltr\" class=\"expr\">n + (n + 1) + (n + 2) = 3n + 3</span>"},{"quoi":"نفكّك المجموع","math":"<span dir=\"ltr\" class=\"expr\">3n + 3 = 3(n + 1)</span>"},{"quoi":"المجموع ليس دائما مضاعفا لـ 9","math":"المجموع <span dir=\"ltr\" class=\"expr\">3(n + 1)</span> ليس دائما مضاعفا لـ 9: مثلا العدد 123"},{"quoi":"الجواب","math":"خطأ"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نفكّك العبارة","math":"<span dir=\"ltr\" class=\"expr\">n<sup>2</sup> + n = n(n + 1)</span>"},{"quoi":"ما هو العدد الأوّلي","math":"العدد الأوّلي له قاسمان فقط: 1 و نفسه"},{"quoi":"العبارة جداء","math":"العبارة مكتوبة جداء عوامل، فهي ليست أوّلية بصفة عامّة"},{"quoi":"مثال مضادّ","math":"من أجل <span dir=\"ltr\" class=\"expr\">n = 7</span> نجد <span dir=\"ltr\" class=\"expr\">7<sup>2</sup> + 7 = 56</span>"},{"quoi":"نفكّك المثال","math":"<span dir=\"ltr\" class=\"expr\">56 = 7(7 + 1)</span>"},{"quoi":"الجواب","math":"خطأ"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"نقسم المعامل الأوّل","math":"<span dir=\"ltr\" class=\"expr\">14 = 7 × 2</span>"},{"quoi":"نقسم الحدّ الثابت","math":"<span dir=\"ltr\" class=\"expr\">63 = 7 × 9</span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">14n + 63 = 7(2n + 9)</span>"},{"quoi":"نستنتج","math":"العبارة مكتوبة <span dir=\"ltr\" class=\"expr\">7 ×</span> عدد صحيح، مهما يكن n"},{"quoi":"الجواب","math":"صواب"}],
