    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"شرط الباقي","math":"الباقي في القسمة على 9 يجب أن يكون أصغر تماما من 9"},{"quoi":"نقارن","math":"<span dir=\"ltr\" class=\"expr\">14 &gt; 9</span>"},{"quoi":"العدد المقترح ليس باقيا","math":"العدد 14 لا يمكن أن يكون باقي قسمة على 9"},{"quoi":"نُظهر الباقي الحقيقي","math":"<span dir=\"ltr\" class=\"expr\">14 = 9 × 1 + 5</span>"},{"quoi":"نعيد كتابة x","math":"<span dir=\"ltr\" class=\"expr\">27y + 14 = 9(3y + 1) + 5</span>"},{"quoi":"الباقي الحقيقي","math":"الباقي هو 5 لأنّ 5 < 9"},{"quoi":"الجواب","math":"خطأ"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"شرط القسمة على 10","math":"العدد يقبل القسمة على 10 إذا كان رقم آحاده 0"},{"quoi":"رقم الآحاد معلوم","math":"رقم آحاد العدد 515a0 هو 0"},{"quoi":"الشرط لا يتعلّق بـ a","math":"الشرط يتعلّق برقم الآحاد وحده، و هو 0 مهما يكن a"},{"quoi":"نستنتج","math":"العدد يقبل القسمة على 10 مهما يكن a"},{"quoi":"الجواب","math":"صواب"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نفكّك العبارة الأولى","math":"<span dir=\"ltr\" class=\"expr\">9n + 6 = 3(3n + 2)</span>"},{"quoi":"نفكّك العبارة الثانية","math":"<span dir=\"ltr\" class=\"expr\">12n + 12 = 3(4n + 4)</span>"},{"quoi":"نستنتج قاسما مشتركا","math":"العدد 3 يقسم العبارتين مهما يكن n"},{"quoi":"نقارن بالتعريف","math":"عددان أوليان فيما بينهما ق.م.أ لهما يساوي 1، و هنا ق.م.أ يقبل القسمة على 3"},{"quoi":"الجواب","math":"خطأ"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"نسمّي رقم المئات","math":"نسمّي n رقم المئات، فتكون الأرقام n و <span dir=\"ltr\" class=\"expr\">n + 1</span> و <span dir=\"ltr\" class=\"expr\">n + 2</span>"},{"quoi":"شرط القسمة على 3","math":"العدد يقبل القسمة على 3 إذا كان مجموع أرقامه يقبل القسمة على 3"},{"quoi":"نحسب مجموع الأرقام","math":"<span dir=\"ltr\" class=\"expr\">n + (n + 1) + (n + 2) = 3n + 3</span>"},{"quoi":"نفكّك المجموع","math":"<span dir=\"ltr\" class=\"expr\">3n + 3 = 3(n + 1)</span>"},{"quoi":"المجموع مضاعف لـ 3","math":"المجموع مضاعف لـ 3 مهما يكن n، فالشرط محقّق دائما"},{"quoi":"الجواب","math":"صواب"}],
