    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"المبدأ","math":"نملأ المراكز الواحد بعد الآخر، ثمّ نضرب عدد الإختيارات"},{"quoi":"المركز 1","math":"كلّ السيّارات ممكنة، أي 6 إختيارات"},{"quoi":"المركز 2","math":"بقي 5 إختيارات بعد شغل 1 من المراكز"},{"quoi":"نضرب الإختيارات","math":"<span dir=\"ltr\" class=\"expr\">6 × 5 = 30</span>"},{"quoi":"النتيجة","math":"عدد الإمكانيات هو 30"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"المبدأ","math":"نملأ كلّ المراكز، من الأوّل إلى الأخير"},{"quoi":"عدد الإختيارات في كل مركز","math":"المركز الأوّل 6، ثمّ 5، و هكذا إلى غاية 1"},{"quoi":"نضرب","math":"<span dir=\"ltr\" class=\"expr\">6 × 5 × 4 × 3 × 2 × 1 = 720</span>"},{"quoi":"النتيجة","math":"عدد الترتيبات الكاملة هو 720"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"المركز الأوّل محجوز","math":"المركز الأوّل له إختيار واحد فقط"},{"quoi":"يبقى الباقي","math":"يبقى 5 في 5 مراكز"},{"quoi":"نضرب","math":"<span dir=\"ltr\" class=\"expr\">1 × 5 × 4 × 3 × 2 × 1 = 120</span>"},{"quoi":"النتيجة","math":"عدد الترتيبات هو 120"}],
