    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"القاعدة","math":"نكتب البسط بدلالة المقام لنُظهر جزءا صحيحا و باقيا"},{"quoi":"ننشر للتحقّق","math":"<span dir=\"ltr\" class=\"expr\">8(n + 4) = 8n + 32</span>"},{"quoi":"نكتب البسط بدلالة المقام","math":"<span dir=\"ltr\" class=\"expr\">8n + 80 = 8(n + 4) + 48</span>"},{"quoi":"نعوّض في M","math":"<span dir=\"ltr\" class=\"expr\">(8n + 80)/(n + 4) = (8(n + 4) + 48)/(n + 4)</span>"},{"quoi":"نفصل الكسرين","math":"<span dir=\"ltr\" class=\"expr\">(8(n + 4) + 48)/(n + 4) = 8(n + 4)/(n + 4) + 48/(n + 4)</span>"},{"quoi":"نختصر الكسر الأوّل","math":"<span dir=\"ltr\" class=\"expr\">8(n + 4)/(n + 4) = 8</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = 8 + 48/(n + 4)</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">M = 8 + 48/(n + 4)</span>"},{"quoi":"الشرط","math":"8 عدد صحيح، إذن M صحيح يعني أنّ <span dir=\"ltr\" class=\"expr\">48/(n + 4)</span> عدد صحيح"},{"quoi":"نترجم","math":"<span dir=\"ltr\" class=\"expr\">n + 4</span> يجب أن يكون قاسما للعدد 48"},{"quoi":"قواسم 48","math":"قواسم 48 الموجبة هي<span dir=\"ltr\" class=\"expr\">: 1 ؛ 2 ؛ 3 ؛ 4 ؛ 6 ؛ 8 ؛ 12 ؛ 16 ؛ 24 ؛ 48</span>، و لكلّ منها مقابله السالب"},{"quoi":"نحسب n في كل حالة","math":"نطرح 4 من كلّ قاسم للحصول على قيمة n"},{"quoi":"النتيجة","math":"القيم الممكنة لـ n هي<span dir=\"ltr\" class=\"expr\">: -52 ؛ -28 ؛ -20 ؛ -16 ؛ -12 ؛ -10 ؛ -8 ؛ -7 ؛ -6 ؛ -5 ؛ -3 ؛ -2 ؛ -1 ؛ 0 ؛ 2 ؛ 4 ؛ 8 ؛ 12 ؛ 20 ؛ 44</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">M = 8 + 48/(-28 + 4)</span>"},{"quoi":"نحسب المقام","math":"<span dir=\"ltr\" class=\"expr\">-28 + 4 = -24</span>"},{"quoi":"نحسب الكسر","math":"<span dir=\"ltr\" class=\"expr\">48 : -24 = -2</span>"},{"quoi":"نجمع","math":"<span dir=\"ltr\" class=\"expr\">8 + -2 = 6</span>"},{"quoi":"نتحقّق بالشكل الأوّل","math":"<span dir=\"ltr\" class=\"expr\">(8 × -28 + 80)/(-28 + 4) = 6</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = 6</span>"}],
