    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"القاعدة","math":"نكتب البسط بدلالة المقام لنُظهر جزءا صحيحا و باقيا"},{"quoi":"ننشر للتحقّق","math":"<span dir=\"ltr\" class=\"expr\">7(n + 1) = 7n + 7</span>"},{"quoi":"نكتب البسط بدلالة المقام","math":"<span dir=\"ltr\" class=\"expr\">7n + 35 = 7(n + 1) + 28</span>"},{"quoi":"نعوّض في M","math":"<span dir=\"ltr\" class=\"expr\">(7n + 35)/(n + 1) = (7(n + 1) + 28)/(n + 1)</span>"},{"quoi":"نفصل الكسرين","math":"<span dir=\"ltr\" class=\"expr\">(7(n + 1) + 28)/(n + 1) = 7(n + 1)/(n + 1) + 28/(n + 1)</span>"},{"quoi":"نختصر الكسر الأوّل","math":"<span dir=\"ltr\" class=\"expr\">7(n + 1)/(n + 1) = 7</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = 7 + 28/(n + 1)</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">M = 7 + 28/(n + 1)</span>"},{"quoi":"الشرط","math":"7 عدد صحيح، إذن M صحيح يعني أنّ <span dir=\"ltr\" class=\"expr\">28/(n + 1)</span> عدد صحيح"},{"quoi":"نترجم","math":"<span dir=\"ltr\" class=\"expr\">n + 1</span> يجب أن يكون قاسما للعدد 28"},{"quoi":"قواسم 28","math":"قواسم 28 الموجبة هي<span dir=\"ltr\" class=\"expr\">: 1 ؛ 2 ؛ 4 ؛ 7 ؛ 14 ؛ 28</span>، و لكلّ منها مقابله السالب"},{"quoi":"نحسب n في كل حالة","math":"نطرح 1 من كلّ قاسم للحصول على قيمة n"},{"quoi":"النتيجة","math":"القيم الممكنة لـ n هي<span dir=\"ltr\" class=\"expr\">: -29 ؛ -15 ؛ -8 ؛ -5 ؛ -3 ؛ -2 ؛ 0 ؛ 1 ؛ 3 ؛ 6 ؛ 13 ؛ 27</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">M = 7 + 28/(3 + 1)</span>"},{"quoi":"نحسب المقام","math":"<span dir=\"ltr\" class=\"expr\">3 + 1 = 4</span>"},{"quoi":"نحسب الكسر","math":"<span dir=\"ltr\" class=\"expr\">28 : 4 = 7</span>"},{"quoi":"نجمع","math":"<span dir=\"ltr\" class=\"expr\">7 + 7 = 14</span>"},{"quoi":"نتحقّق بالشكل الأوّل","math":"<span dir=\"ltr\" class=\"expr\">(7 × 3 + 35)/(3 + 1) = 14</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = 14</span>"}],
