  { id: "arith9-9-4", chapitre: "arith9", chapitreNom: "الحساب و القابلية للقسمة", niveau: 9,
    rubrique: "ex9", rubriqueNom: "M = (an + b)/(n + c) — متى يكون صحيحا", difficulte: "difficile",
    enonce: "<span class=\"q\">1) </span>لتكن العبارة <span dir=\"ltr\" class=\"expr\">M = (4n + 36)/(n + 1)</span> حيث n عدد صحيح نسبي مخالف لـ <span dir=\"ltr\" class=\"expr\">-1</span> بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = 4 + 32/(n + 1)</span><br><span class=\"q\">2) </span>لتكن العبارة <span dir=\"ltr\" class=\"expr\">M = (4n + 36)/(n + 1)</span> حيث n عدد صحيح نسبي مخالف لـ <span dir=\"ltr\" class=\"expr\">-1</span> بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = 4 + 32/(n + 1)</span> أوجد كلّ القيم الممكنة للعدد النسبي n حتّى يكون M عددا صحيحا نسبيا<br><span class=\"q\">3) </span>لتكن العبارة <span dir=\"ltr\" class=\"expr\">M = (4n + 36)/(n + 1)</span> حيث n عدد صحيح نسبي مخالف لـ <span dir=\"ltr\" class=\"expr\">-1</span> بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = 4 + 32/(n + 1)</span> احسب القيمة العددية لـ M إذا كان <span dir=\"ltr\" class=\"expr\">n = 31</span> علما أنّ <span dir=\"ltr\" class=\"expr\">M = (4n + 36)/(n + 1)</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"القاعدة","math":"نكتب البسط بدلالة المقام لنُظهر جزءا صحيحا و باقيا"},{"quoi":"ننشر للتحقّق","math":"<span dir=\"ltr\" class=\"expr\">4(n + 1) = 4n + 4</span>"},{"quoi":"نكتب البسط بدلالة المقام","math":"<span dir=\"ltr\" class=\"expr\">4n + 36 = 4(n + 1) + 32</span>"},{"quoi":"نعوّض في M","math":"<span dir=\"ltr\" class=\"expr\">(4n + 36)/(n + 1) = (4(n + 1) + 32)/(n + 1)</span>"},{"quoi":"نفصل الكسرين","math":"<span dir=\"ltr\" class=\"expr\">(4(n + 1) + 32)/(n + 1) = 4(n + 1)/(n + 1) + 32/(n + 1)</span>"},{"quoi":"نختصر الكسر الأوّل","math":"<span dir=\"ltr\" class=\"expr\">4(n + 1)/(n + 1) = 4</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = 4 + 32/(n + 1)</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">M = 4 + 32/(n + 1)</span>"},{"quoi":"الشرط","math":"4 عدد صحيح، إذن M صحيح يعني أنّ <span dir=\"ltr\" class=\"expr\">32/(n + 1)</span> عدد صحيح"},{"quoi":"نترجم","math":"<span dir=\"ltr\" class=\"expr\">n + 1</span> يجب أن يكون قاسما للعدد 32"},{"quoi":"قواسم 32","math":"قواسم 32 الموجبة هي<span dir=\"ltr\" class=\"expr\">: 1 ؛ 2 ؛ 4 ؛ 8 ؛ 16 ؛ 32</span>، و لكلّ منها مقابله السالب"},{"quoi":"نحسب n في كل حالة","math":"نطرح 1 من كلّ قاسم للحصول على قيمة n"},{"quoi":"النتيجة","math":"القيم الممكنة لـ n هي<span dir=\"ltr\" class=\"expr\">: -33 ؛ -17 ؛ -9 ؛ -5 ؛ -3 ؛ -2 ؛ 0 ؛ 1 ؛ 3 ؛ 7 ؛ 15 ؛ 31</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">M = 4 + 32/(31 + 1)</span>"},{"quoi":"نحسب المقام","math":"<span dir=\"ltr\" class=\"expr\">31 + 1 = 32</span>"},{"quoi":"نحسب الكسر","math":"<span dir=\"ltr\" class=\"expr\">32 : 32 = 1</span>"},{"quoi":"نجمع","math":"<span dir=\"ltr\" class=\"expr\">4 + 1 = 5</span>"},{"quoi":"نتحقّق بالشكل الأوّل","math":"<span dir=\"ltr\" class=\"expr\">(4 × 31 + 36)/(31 + 1) = 5</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = 5</span>"}],
    indice: "اكتب البسط بدلالة n + 1: 4n + 36 = 4(n + 1) + 32" }
